def stall_time(bitrate, bandwidth, buffer_s, length_s):
    if bandwidth >= bitrate:
        return 0
    t = buffer_s / (1 - bandwidth / bitrate)
    if t >= length_s:
        return 0
    return round(t, 1)

def reply_all(sender, to, cc, bcc, replier):
    s = set([sender] + list(to) + list(cc))
    s.discard(replier)
    return sorted(s)

def visible(to, cc, bcc, viewer):
    s = set(to) | set(cc)
    if viewer in bcc:
        s.add(viewer)
    return sorted(s)
